def transform(grid):
    g=[r[:] for r in grid]
    h=len(g)
    sep=[i for i,r in enumerate(g) if all(x==3 for x in r)]
    if sep:
        a,b=min(sep),max(sep)
        for k,r in enumerate(range(a,b+1)):
            src=b+2+k
            if src<h: g[r]=g[src][:]
    return g
